  <script>
    // Header scroll effect
    const header = document.getElementById('header');
    window.addEventListener('scroll', () => {
      header.classList.toggle('scrolled', window.scrollY > 20);
    });

    // Product Carousel
    const track = document.getElementById('carouselTrack');
    const prevBtn = document.getElementById('carouselPrev');
    const nextBtn = document.getElementById('carouselNext');
    const dotsContainer = document.getElementById('carouselDots');
    const cards = track.querySelectorAll('.product-card');
    let currentIndex = 0;

    function getVisibleCards() {
      const w = window.innerWidth;
      if (w <= 480) return 1;
      if (w <= 768) return 2;
      if (w <= 1024) return 3;
      return 4;
    }

    function getMaxIndex() {
      return Math.max(0, cards.length - getVisibleCards());
    }

    function updateCarousel() {
      const card = cards[0];
      const gap = 20;
      const cardWidth = card.offsetWidth + gap;
      track.style.transform = `translateX(-${currentIndex * cardWidth}px)`;
      updateDots();
    }

    function updateDots() {
      const maxIdx = getMaxIndex();
      const dotCount = maxIdx + 1;
      dotsContainer.innerHTML = '';
      for (let i = 0; i < dotCount; i++) {
        const dot = document.createElement('button');
        dot.className = 'carousel-dot' + (i === currentIndex ? ' active' : '');
        dot.setAttribute('aria-label', `Go to slide ${i + 1}`);
        dot.addEventListener('click', () => { currentIndex = i; updateCarousel(); });
        dotsContainer.appendChild(dot);
      }
    }

    prevBtn.addEventListener('click', () => {
      currentIndex = Math.max(0, currentIndex - 1);
      updateCarousel();
    });

    nextBtn.addEventListener('click', () => {
      currentIndex = Math.min(getMaxIndex(), currentIndex + 1);
      updateCarousel();
    });

    window.addEventListener('resize', () => {
      currentIndex = Math.min(currentIndex, getMaxIndex());
      updateCarousel();
    });

    updateCarousel();

    // Store Locator
    const storeInput = document.getElementById('storeInput');
    const storeSearchBtn = document.getElementById('storeSearchBtn');
    const storeResults = document.getElementById('storeResults');

    function searchStores() {
      const zip = storeInput.value.trim();
      if (zip.length >= 3) {
        storeResults.classList.add('visible');
        storeResults.style.animation = 'fadeInUp 0.4s ease-out';
      }
    }

    storeSearchBtn.addEventListener('click', searchStores);
    storeInput.addEventListener('keypress', (e) => { if (e.key === 'Enter') searchStores(); });

    // Newsletter
    const newsletterForm = document.getElementById('newsletterForm');
    const newsletterInput = document.getElementById('newsletterInput');
    const newsletterConfirm = document.getElementById('newsletterConfirm');

    newsletterForm.addEventListener('submit', (e) => {
      e.preventDefault();
      if (newsletterInput.value.trim()) {
        newsletterConfirm.classList.add('visible');
        newsletterInput.value = '';
      }
    });

    // Scroll-triggered animations
    const observerOptions = { threshold: 0.15, rootMargin: '0px 0px -40px 0px' };
    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add('animate-in');
          observer.unobserve(entry.target);
        }
      });
    }, observerOptions);

    document.querySelectorAll('.section-header, .product-card, .seasonal-card, .category-card, .highlight-item, .store-result-card').forEach(el => {
      observer.observe(el);
    });
  </script>

